UPDATE ai_prompt_templates
SET body = body || ' Важно: три направления должны быть действительно разными по формуле комплекта, силуэту, палитре, обуви и главному акценту. Не повторяй один и тот же жакет, платье-футляр, брючный костюм или total black для разных событий. Привязывай рекомендации к конкретному событию: свидание, офис, свадьба гостем, вечеринка, отпуск, фотосессия и собеседование должны иметь разные уровни нарядности, фактуры и уместности. Используй современные, но носибельные приемы: выразительная фактура, layering, актуальная длина, мягкая драпировка, cropped jacket, жилет, ремень, brooch/core аксессуар, metallic или butter-yellow/бордо/оливковый/ледяной голубой акцент там, где это уместно.'
WHERE template_key = 'stylist.trends_ru'
  AND body NOT LIKE '%три направления должны быть действительно разными%';

UPDATE ai_prompt_templates
SET body = body || ' Соблюдай конкретную формулу варианта из системного описания. Не превращай любой сценарий в одинаковое платье, базовый костюм или черный жакет. Каждый вариант должен визуально отличаться от соседних по силуэту, цветовой температуре, обуви и аксессуарам, но оставаться реалистичным товарным образом.'
WHERE template_key = 'stylist.preview_tryon_ru'
  AND body NOT LIKE '%конкретную формулу варианта%';
